 p_id=>wwv_flow_imp.id(8118048413893990406)
,p_chart_id=>wwv_flow_imp.id(8118048048320990402)
,p_static_id=>'cte-late-pct'
,p_seq=>20
,p_name=>'Late %'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH inst AS (',
'    SELECT i.installment_status,',
'           i.written_off_amt,',
'           p.payment_plan,',
'           p.autopay_flag,',
'           p.score_tier',
'    FROM   installments i',
'    JOIN   policies p ON p.policy_id = i.policy_id',
')',
'SELECT payment_plan,',
'       COUNT(*)                                                                    AS installments,',
'       ROUND(100 * AVG(CASE WHEN installment_status = ''PAID_LATE'' THEN 1 ELSE 0 END), 2) AS late_pct,',
'       ROUND(100 * AVG(CASE WHEN installment_status = ''MISSED''    THEN 1 ELSE 0 END), 2) AS missed_pct,',
'       SUM(written_off_amt)                                                        AS written_off',
'FROM   inst',
'GROUP  BY payment_plan',
'ORDER  BY missed_pct DESC;'))
,p_items_value_column_name=>'LATE_PCT'
,p_items_label_column_name=>'PAYMENT_PLAN'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
,p_created_on=>wwv_flow_imp.dz('20261026181251Z')
,p_updated_on=>wwv_flow_imp.dz('20261026184424Z')
,p_created_by=>'ANTDIA4309@STUDENTS.ECPI.EDU'
,p_updated_by=>'ANTDIA4309@STUDENTS.ECPI.EDU'
);
