,p_seq=>10
,p_name=>'Missed %'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH inst AS (',
'    SELECT i.installment_status,',
'           i.written_off_amt,',
'           p.payment_plan,',
'           p.autopay_flag,',
