wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(8118049851271990419)
,p_name=>'Write-Off Impact'
,p_static_id=>'write-off-impact'
,p_title=>'Projected Write-Off Impact'
,p_template=>4075786578761660127
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH base AS (',
'    SELECT p.autopay_flag,',
'           COUNT(*)               AS n,',
'           SUM(i.written_off_amt) AS wo',
'    FROM   installments i',
'    JOIN   policies p ON p.policy_id = i.policy_id',
'    WHERE  p.payment_plan <> ''PIF''',
'    GROUP  BY p.autopay_flag',
'),',
'r AS (',
'    SELECT MAX(CASE WHEN autopay_flag = ''Y'' THEN wo / n END)       AS wo_per_inst_y,',
'           MAX(CASE WHEN autopay_flag = ''N'' THEN wo / n END)       AS wo_per_inst_n,',
'           SUM(n)                                                  AS total_n,',
'           SUM(CASE WHEN autopay_flag = ''Y'' THEN n END) / SUM(n)   AS current_share,',
'           SUM(wo)                                                 AS current_wo',
'    FROM   base',
')',
'SELECT ROUND(100 * current_share, 1)                                         AS current_autopay_pct,',
'       :p2_target_pct                                                           AS target_autopay_pct,',
'       ROUND(current_wo, 2)                                                  AS current_writeoff,',
'       ROUND(total_n * ((:p2_target_pct / 100) * wo_per_inst_y',
'                    + (1 - :p2_target_pct / 100) * wo_per_inst_n), 2)           AS projected_writeoff,',
'       ROUND(current_wo - total_n * ((:p2_target_pct / 100) * wo_per_inst_y',
'                    + (1 - :p2_target_pct / 100) * wo_per_inst_n), 2)           AS projected_savings',
'FROM   r;'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P2_TARGET_PCT'
,p_lazy_loading=>false
,p_query_row_template=>2542081983073888486
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'SHOW_ALL'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
